<?php namespace App\Http\Controllers; use App\Http\Requests\CategoryRequest; use App\Models\Category; use Illuminate\Http\Request; class CategoryController extends Controller { public function __construct(){ $this->middleware('permission:category.manage'); } public function index(Request $r){$categories=Category::when($r->q,fn($q,$v)=>$q->where('nama_kategori','like',"%$v%"))->latest()->paginate(10)->withQueryString();return view('categories.index',compact('categories'));} public function create(){return view('categories.form',['category'=>new Category]);} public function store(CategoryRequest $r){Category::create($r->validated());return to_route('categories.index')->with('success','Kategori ditambahkan.');} public function edit(Category $category){return view('categories.form',compact('category'));} public function update(CategoryRequest $r,Category $category){$category->update($r->validated());return to_route('categories.index')->with('success','Kategori diperbarui.');} public function destroy(Category $category){$category->delete();return back()->with('success','Kategori dihapus.');}}
